const originals=new WeakMap();
export function translateText(text,language){
 if(language==='en')return text;const i=language==='es'?0:1;if(pairs[text])return pairs[text][i];
 const next=text.match(/^(.*) →$/);if(next&&pairs[next[1]])return pairs[next[1]][i]+' →';
 const rules=[[/^Evidence receipt · (\d+) recorded events$/,(_,n)=>i?`Comprovante · ${n} eventos registrados`:`Registro de evidencia · ${n} eventos registrados`],[/^CONTINUE THE STORY \/ (\d+) OF 6$/,(_,n)=>i?`CONTINUE / ${n} DE 6`:`CONTINÚA / ${n} DE 6`],[/^Revision history · (\d+) changes$/,(_,n)=>i?`Histórico · ${n} alterações`:`Historial · ${n} cambios`],[/^AT (.*) S$/,(_,n)=>i?`AOS ${n} S`:`EN ${n} S`],[/^Your choice: (.*)$/,(_,n)=>i?`Sua escolha: ${n}`:`Tu elección: ${n}`],[/^(.*) \/ ([\d.]+) S · LOCAL INSPECTION$/,(_,title,n)=>`${(pairs[Object.keys(pairs).find(k=>k.toUpperCase()===title)]?.[i]||title).toUpperCase()} / ${n} S · ${i?'INSPEÇÃO LOCAL':'INSPECCIÓN LOCAL'}`],[/^(\d+)\/(\d+) passes complete · (\d+) goals · same (\d+) event IDs$/,(_,a,b,c,d)=>i?`${a}/${b} passes completos · ${c} gols · mesmos ${d} IDs de eventos`:`${a}/${b} pases completos · ${c} goles · mismos ${d} ID de eventos`]];
 for(const[re,fn]of rules)if(re.test(text))return text.replace(re,fn);
 return text.replace('Source: ',i?'Fonte: ':'Fuente: ').replace(' · PASS',' · PASE').replace(' · complete',i?' · completo':' · completo');
}
export function localizeStudio(root,language){const walk=document.createTreeWalker(root,root.ownerDocument.defaultView.NodeFilter.SHOW_TEXT);let n;while(n=walk.nextNode()){if(n.parentElement?.closest('code,option'))continue;let original=originals.get(n);if(original===undefined){original=n.textContent;originals.set(n,original);}n.textContent=translateText(original,language);}root.lang=language;}
